 bool bindAll(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_)return false;if(!script_.bindAll(d,image,size)||!voices_.bindVerifiedFirmware(d,image,size)||!keys_.bindBootResources(d,image,size)||!keys_.bindMirroredFirmware(d,image,size)||!adc_.bindVerifiedFirmware(d,image,size)||!volume_.bindBootResources(d,image,size)||!volume_.bindMirroredFirmware(d,image,size)||!cleanup_.bindVerifiedFirmware(d,image,size)||!entry_.bindVerifiedFirmware(d,image,size)||!note_.bindVerifiedFirmware(d,image,size)||!expression_.bindVerifiedFirmware(d,image,size)||!trigger_.bindVerifiedFirmware(d,image,size)||!display_.bindVerifiedFirmware(d,image,size)||!realtime_.bindVerifiedFirmware(d,image,size)||!program_.bindVerifiedFirmware(d,image,size)||!programInit_.bindVerifiedFirmware(d,image,size)||!programPanel_.bindVerifiedFirmware(d,image,size))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return script_.active();}bool start(){return bound_&&owner_==Owner::None&&script_.start();}void reset(){script_.reset();voices_.reset();keys_.reset();adc_.reset();volume_.reset();cleanup_.reset();entry_.reset();note_.reset();expression_.reset();trigger_.reset();display_.reset();realtime_.reset();program_.reset();programInit_.reset();programPanel_.reset();programHardware_=nullptr;displayPanel_=nullptr;displayLcd_=nullptr;displayNumeric_=nullptr;owner_=Owner::None;}
 Request request(const ControllerPeriodicUiRuntime&ui,const ControllerMidiServices&midi,const ControllerVoiceServices&voice)const{if(owner_==Owner::PeriodicUi)return {{},ui.request()};if(owner_==Owner::Midi)return {{},{},midi.externalRequest(voice)};if(owner_==Owner::Display)return {{},{},{},display_.request()};if(owner_==Owner::None)return {script_.request()};return {};}
 Route route(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,ControllerArpServices&arp,ControllerVoiceServices&voice,ControllerPeriodicUiRuntime&ui,ControllerMidiServices&midi,ControllerLcdRuntime&lcd,ControllerNumericDisplayRuntime&numeric,ControllerPanelHardwareRuntime&panel){if(bound_!=&d||!active()||!irq.boundTo(d)||!dsp.boundTo(d)||!arp.boundTo(d)||!voice.boundTo(d)||!ui.boundTo(d)||!midi.boundTo(d))return Route::Invalid;if(owner_==Owner::Program)return program_.routeServices(d,{dsp,*programHardware_,programPanel_,programInit_,voices_})?Route::Ready:Route::Invalid;if(owner_==Owner::Arp)return arp.route(d,dsp)==ControllerArpServices::Route::Ready?Route::Ready:Route::Invalid;if(owner_==Owner::Feedback){auto r=voice.routeFeedback(d,dsp);return r==ControllerVoiceServices::Route::Ready?Route::Ready:r==ControllerVoiceServices::Route::External?Route::External:Route::Invalid;}if(owner_==Owner::PeriodicUi){auto r=ui.request();if(r.service==ControllerPeriodicUiRuntime::Service::Clock)return ui.beginClock(d,dsp)?Route::Ready:Route::Invalid;return r.service==ControllerPeriodicUiRuntime::Service::None?Route::Ready:Route::External;}if(owner_==Owner::Display)return display_.request().service==ControllerStartupDisplayRuntime::Service::None?Route::Ready:Route::External;if(owner_==Owner::Midi){auto r=midi.routeDirect(d,irq,dsp,voice,lcd,numeric,panel);return r==ControllerMidiServices::Route::Ready?Route::Ready:r==ControllerMidiServices::Route::External?Route::External:Route::Invalid;}if(owner_!=Owner::None)return Route::Ready;auto q=script_.request();switch(q.service){case S::None:return Route::Ready;case S::LoadProgram:if(!panel.boundTo(d)||panel.active()||!program_.start())return Route::Invalid;programHardware_=&panel;owner_=Owner::Program;break;case S::ReleaseVoices:if(!voices_.start(0,false))return Route::Invalid;owner_=Owner::Voices;break;case S::Arp:if(!arp.start())return Route::Invalid;owner_=Owner::Arp;break;case S::VoiceFeedback:case S::DspFeedback:if(!voice.startFeedback(q.service==S::VoiceFeedback?ControllerVoiceFeedbackRuntime::Kind::VoiceFeedback:ControllerVoiceFeedbackRuntime::Kind::DspFeedback))return Route::Invalid;owner_=Owner::Feedback;break;case S::PeriodicUi:if(!ui.start())return Route::Invalid;owner_=Owner::PeriodicUi;break;case S::Keyboard:if(!keys_.start(ControllerStartupKeyboardRuntime::Kind::Dequeue))return Route::Invalid;owner_=Owner::Keyboard;break;case S::Adc:if(!adc_.start(ControllerAdcEventRuntime::Kind::Dequeue))return Route::Invalid;owner_=Owner::Adc;break;case S::Volume:if(!volume_.start(q.value))return Route::Invalid;owner_=Owner::Volume;break;case S::ClearNotes:case S::ResetClock:if(!cleanup_.start(q.service==S::ClearNotes?ControllerScriptCleanupRuntime::Kind::ClearNotes:ControllerScriptCleanupRuntime::Kind::ResetExternal))return Route::Invalid;cleanupService_=q.service;owner_=Owner::Cleanup;break;case S::ResetInputs:if(!entry_.start())return Route::Invalid;owner_=Owner::ResetInputs;break;case S::RefreshDisplay:if(!panel.boundTo(d)||!lcd.boundTo(d)||!numeric.boundTo(d)||panel.active()||lcd.active()||numeric.active()||!display_.start())return Route::Invalid;displayPanel_=&panel;displayLcd_=&lcd;displayNumeric_=&numeric;owner_=Owner::Display;break;case S::MidiHandler:{using H=ControllerForegroundRuntime::MidiHandler;if(q.handler==0x2dc8||q.handler==0x2d7e){if(!note_.start(q.handler==0x2dc8?MidiNoteEventTask::Kind::On:MidiNoteEventTask::Kind::Off,q.payload))return Route::Invalid;owner_=Owner::Note;break;}if(q.handler==0x2df0||q.handler==0x2e18){if(!expression_.start(q.handler==0x2df0?MidiExpressionEventTask::Kind::PitchBend:MidiExpressionEventTask::Kind::ChannelPressure,q.payload))return Route::Invalid;owner_=Owner::Expression;break;}H h=q.handler==0x2e34?H::ControlChange:q.handler==0x33ca?H::ProgramChange:q.handler==0x2f68?H::SysExStart:q.handler==0x2f6c?H::SysExEnd:H::Unknown;if(h!=H::Unknown){if(!midi.startHandler(h,q.channel,q.payload))return Route::Invalid;owner_=Owner::Midi;break;}if(q.handler==0x33f2||q.handler==0x33ec){if(!realtime_.start(q.handler==0x33f2))return Route::Invalid;owner_=Owner::Realtime;break;}return Route::External;}default:return Route::External;}return Route::Ready;}
 bool completeExternal(const Request&r,ControllerPeriodicUiRuntime&ui,ControllerMidiServices&midi,ControllerVoiceServices&voice,uint32_t value=0){if(owner_==Owner::PeriodicUi)return ui.completeService(r.periodic,uint8_t(value));if(owner_==Owner::Midi)return midi.completeExternal(r.midi,voice,value);if(owner_==Owner::Display){if(!display_.completeService(r.display.service))return false;if(!display_.active()){displayPanel_=nullptr;displayLcd_=nullptr;displayNumeric_=nullptr;owner_=Owner::None;return script_.completeService(S::RefreshDisplay);}return true;}if(owner_==Owner::None)return script_.completeService(r.script.service,value);return false;}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,const ControllerDspTransferRuntime&dsp,const ControllerArpServices&arp,const ControllerVoiceServices&voice,const ControllerPeriodicUiRuntime&ui,const ControllerMidiServices&midi)const{if(bound_!=&d||!active())return 0;switch(owner_){case Owner::Program:return program_.nextClocks(d,irq,ControllerProgramStateRuntime::ConstServices{dsp,*programHardware_,programPanel_,programInit_,voices_});case Owner::Voices:return voices_.nextClocks(d,irq,dsp);case Owner::Arp:return arp.nextClocks(d,irq);case Owner::Feedback:return voice.nextFeedback(d,irq,dsp);case Owner::Keyboard:return keys_.nextClocks(d,irq);case Owner::Adc:return adc_.nextClocks(d,irq);case Owner::Volume:return volume_.nextClocks(d,irq,dsp);case Owner::Cleanup:return cleanup_.nextClocks(d,irq);case Owner::ResetInputs:return entry_.nextClocks(d,irq);case Owner::PeriodicUi:return ui.nextClocks(d,irq);case Owner::Note:return note_.nextClocks(d,irq,dsp,trigger_);case Owner::Expression:return expression_.nextClocks(d,irq,dsp);case Owner::Midi:return midi.nextClocks(d,irq,dsp,voice);case Owner::Display:return display_.nextClocks(d,irq,*displayPanel_,*displayNumeric_,*displayLcd_);case Owner::Realtime:return realtime_.nextClocks(d,irq,dsp);default:return script_.nextClocks(d,irq);}}
 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,ControllerArpServices&arp,ControllerVoiceServices&voice,ControllerPeriodicUiRuntime&ui,ControllerMidiServices&midi,unsigned budget){if(bound_!=&d)return {0,false,Block::NotBound};if(!active())return {0,false,Block::Inactive};if(irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return {0,false,Block::NeedsInterrupt};unsigned c=0;bool done=false;uint32_t value=0;switch(owner_){case Owner::Program:{auto r=program_.advanceBefore(d,irq,{dsp,*programHardware_,programPanel_,programInit_,voices_},budget);c=r.clocks;done=r.returned;if(done)programHardware_=nullptr;break;}case Owner::Voices:{auto r=voices_.advanceBefore(d,irq,dsp,budget);c=r.clocks;done=r.returned;break;}case Owner::Arp:{auto r=arp.advanceBefore(d,irq,budget);c=r.clocks;done=r.returned;break;}case Owner::Feedback:{auto r=voice.advanceFeedback(d,irq,dsp,budget);c=r.clocks;done=r.returned;break;}case Owner::Keyboard:{auto r=keys_.advanceBefore(d,irq,budget);c=r.clocks;done=r.returned;value=keys_.event();break;}case Owner::Adc:{auto r=adc_.advanceBefore(d,irq,budget);c=r.clocks;done=r.returned;value=adc_.event();break;}case Owner::Volume:{auto r=volume_.advanceBefore(d,irq,dsp,budget);c=r.clocks;done=r.returned;break;}case Owner::Cleanup:{auto r=cleanup_.advanceBefore(d,irq,budget);c=r.clocks;done=r.returned;break;}case Owner::ResetInputs:{auto r=entry_.advanceBefore(d,irq,budget);c=r.clocks;done=r.returned;break;}case Owner::PeriodicUi:{auto r=ui.advanceBefore(d,irq,budget);c=r.clocks;done=r.returned;break;}case Owner::Note:{auto r=note_.advanceBefore(d,irq,dsp,trigger_,budget);c=r.clocks;done=r.returned;break;}case Owner::Expression:{auto r=expression_.advanceBefore(d,irq,dsp,budget);c=r.clocks;done=r.returned;break;}case Owner::Midi:{auto r=midi.advanceDirect(d,irq,dsp,voice,budget);c=r.clocks;done=r.returned;break;}case Owner::Display:{auto r=display_.advanceBefore(d,irq,*displayPanel_,*displayNumeric_,*displayLcd_,budget);c=r.clocks;done=r.returned;if(done){displayPanel_=nullptr;displayLcd_=nullptr;displayNumeric_=nullptr;}break;}case Owner::Realtime:{auto r=realtime_.advanceBefore(d,irq,dsp,budget);c=r.clocks;done=r.returned;break;}default:{auto r=script_.advanceBefore(d,irq,budget);return {r.clocks,r.returned,r.blocked==P::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==P::Block::Service?Block::External:r.blocked==P::Block::None?Block::None:Block::Invalid};}}
 if(done){auto s=script_.request().service;if(!script_.completeService(s,value))return {c,false,Block::Invalid};owner_=Owner::None;}return {c,false,c?Block::None:Block::External};}
